<?php
/** Disposable-site only: actual native schema, template insertion, Apply and rollback. */
if(!defined('ABSPATH')||!getenv('ACE_MODULE_FIXTURE_DIR')){exit(1);}
wp_set_current_user(get_user_by('login','qa_admin')->ID);set_current_screen('suiteedge-migrator-mapping');
$checks=0;$check=function($ok,$label)use(&$checks){if(!$ok){throw new RuntimeException('FAIL: '.$label);}$checks++;};
$builder=new SuiteEdge\Migrator\Elementor\DocumentBuilder();$serializer=new SuiteEdge\Migrator\Elementor\Classic\Serializer();$validator=new SuiteEdge\Migrator\Elementor\Validator();
$source='[et_pb_section][et_pb_row][et_pb_column type="4_4"][et_pb_counters module_id="qa-skills" background_color="#eeeeee" bar_bg_color="#123456" title_font="Arial|700" title_font_size="18px" title_font_size_tablet="16px" title_font_size_phone="13px" percent_font="Arial|400" percent_text_color="#ffffff"][et_pb_counter percent="0" height="24px"]Zero[/et_pb_counter][et_pb_counter percent="37.5" height="30px" height_tablet="4vw" height_phone="12px"]Fraction[/et_pb_counter][et_pb_counter percent="100"]Full[/et_pb_counter][/et_pb_counters][et_pb_counters use_percentages="off" use_percentages_tablet="on" use_percentages_phone="off"][et_pb_counter percent="60"]Responsive display[/et_pb_counter][/et_pb_counters][et_pb_counter percent="0" /][/et_pb_column][/et_pb_row][/et_pb_section]';
$data=$serializer->serialize($builder->build($source));$check($validator->validate($data,true),'new controls validate installed native schema');
$source_bars=0;
foreach(['legacy','divi4'] as $key){$nodes=json_decode(file_get_contents(getenv('ACE_MODULE_FIXTURE_DIR').'/bars-'.$key.'-nodes.json'),true);$presets=$key==='divi4'?json_decode(file_get_contents(getenv('ACE_MODULE_FIXTURE_DIR').'/bars-divi4-presets.json'),true):[];foreach($nodes as $n){$d=$serializer->serialize($builder->build($n['original_shortcode'],['presets'=>$presets]));$check($validator->validate($d,true),'actual fixture native controls '.$key);$check(!$builder->warnings,'actual fixture mappings accepted '.$key);$source_bars+=count($n['children']);}}
$library=Elementor\Plugin::$instance->templates_manager->get_source('local');$template=$library->save_item(['title'=>'QA Bar Counters','type'=>'page','content'=>$data,'page_settings'=>[]]);if(is_wp_error($template)){throw new RuntimeException($template->get_error_message());}
$inserted=$library->get_data(['template_id'=>$template]);$check($inserted['content'][0]['id']!==$data[0]['id'],'native insertion regenerates IDs');$check($validator->validate($inserted['content'],true),'inserted controls remain valid');
$repo=new SuiteEdge\Migrator\Jobs\JobRepository();$runner=new SuiteEdge\Migrator\Jobs\BatchRunner($repo);$backup=new SuiteEdge\Migrator\Import\BackupEngine();
$source_id=(new SuiteEdge\Migrator\Import\SourceRepository())->save(wp_json_encode(['data'=>$source]),'bar-counters.json');$targets=[];$before=[];
for($i=0;$i<2;$i++){$id=wp_insert_post(['post_type'=>'page','post_status'=>'draft','post_title'=>'QA Bar Apply '.$i,'post_content'=>'Preserve original '.$i]);$targets[]=$id;$before[$id]=$backup->fingerprint($id);}
$job=new SuiteEdge\Migrator\Jobs\Job();$job->settings=['output_engine'=>'classic','dry_run'=>true,'assets'=>[]];foreach($targets as$id){$job->items[]=['source_id'=>$source_id,'layout_index'=>0,'name'=>'bar-counters.json','target_page_id'=>$id,'status'=>'pending'];}$job->summary['total']=2;$repo->save($job);
for($i=0;$i<2;$i++){$runner->process_batch($job->id);}$saved=$repo->get($job->id);$check($saved->status==='completed','multi-page analysis completes');$hashes=array_column($saved->items,'output_hash');foreach($targets as$id){$check($backup->fingerprint($id)===$before[$id],'analysis preserves original target');}
(new SuiteEdge\Migrator\Jobs\SavedOutputApplier())->queue([$job->id=>[0,1]],true);for($i=0;$i<2;$i++){$runner->process_batch($job->id);}$applied=$repo->get($job->id);
foreach($targets as$i=>$id){$check($applied->items[$i]['status']==='converted'&&$applied->items[$i]['output_hash']===$hashes[$i],'corresponding saved output applied without reconversion');$check(get_post_meta($id,'_elementor_edit_mode',true)==='builder','applied target is editable Elementor');}
$check($runner->rollback($job->id)['status']==='rolled_back','bulk rollback completes');foreach($targets as$id){$check($backup->fingerprint($id)===$before[$id],'exact original restored');}
foreach(['percent="101"','background_image="https://example.test/a.jpg"','_module_preset="missing"'] as $bad){$blocked=$serializer->serialize($builder->build('[et_pb_counters][et_pb_counter '.$bad.']Protected[/et_pb_counter][/et_pb_counters]'));try{(new SuiteEdge\Migrator\Jobs\SavedOutputApplier())->validate_output($blocked);$check(false,'block invalid output');}catch(UnexpectedValueException $e){$check(true,'invalid compound cannot bypass saved Apply');}}
$preview=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>'QA Bar Counter browser']);update_post_meta($preview,'_wp_page_template','elementor_canvas');update_post_meta($preview,'_elementor_edit_mode','builder');
Elementor\Plugin::$instance->documents->get($preview)->save(['elements'=>$inserted['content'],'settings'=>[]]);(new SuiteEdge\Migrator\Elementor\CssRegenerator())->regenerate($preview);
$html=Elementor\Plugin::$instance->frontend->get_builder_content_for_display($preview);
foreach(['Zero','Fraction','Full','Responsive display','aria-valuenow="0"','aria-valuenow="37.5"','aria-valuenow="100"','ace-bar-counter'] as$text){$check(strpos($html,$text)!==false,'native frontend retains '.$text);}
$check(substr_count($html,'role="progressbar"')===5,'all native tracks render including unlabeled zero');
$stack=Elementor\Plugin::$instance->widgets_manager->get_widget_types('progress')->get_stack();
file_put_contents(getenv('ACE_MODULE_FIXTURE_DIR').'/bars-wordpress-'.(defined('DB_ENGINE')?'sqlite':'mariadb').'.json',wp_json_encode(['assertions'=>$checks,'official_source_items'=>$source_bars,'wordpress'=>get_bloginfo('version'),'elementor'=>ELEMENTOR_VERSION,'page_id'=>$preview,'url'=>get_permalink($preview),'job_id'=>$job->id,'controls'=>array_keys(array_merge($stack['controls'],$stack['style_controls']??[]))],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
echo 'PASS: '.$checks.' bar-counter WordPress assertions'.PHP_EOL;
